// src/components/UserSection.js
import React, { useState } from "react";

const UserSection = () => {
  const [formData, setFormData] = useState({
    name: "",
    phone: "",
    marketingConsent: true,
    interests: [],
  });

  const [formSubmitted, setFormSubmitted] = useState(false);
  const [error, setError] = useState("");

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleCheckboxChange = (e) => {
    const { name, value, checked } = e.target;

    // Handle marketing consent checkbox
    if (name === "marketingConsent") {
      setFormData((prev) => ({
        ...prev,
        marketingConsent: checked,
      }));
      return;
    }

    // Handle interests checkboxes
    setFormData((prev) => {
      if (checked) {
        return { ...prev, interests: [...prev.interests, value] };
      } else {
        return {
          ...prev,
          interests: prev.interests.filter((interest) => interest !== value),
        };
      }
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    // Basic validation
    if (!formData.name || !formData.phone) {
      setError("Name and phone number are required");
      return;
    }

    // Validate phone number format
    const phoneRegex = /^\+?[0-9]{10,15}$/;
    if (!phoneRegex.test(formData.phone)) {
      setError("Please enter a valid phone number (10-15 digits)");
      return;
    }

    try {
      const response = await fetch("/api/users/register", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      const data = await response.json();

      if (response.ok) {
        setFormSubmitted(true);
        setFormData({
          name: "",
          phone: "",
          marketingConsent: true,
          interests: [],
        });
      } else {
        setError(data.message || "Registration failed. Please try again.");
      }
    } catch (error) {
      console.error("Error submitting form:", error);
      setError("Connection error. Please try again later.");
    }
  };

  return (
    <section id="users" className="py-16 px-4 bg-snap-light">
      <div className="container mx-auto">
        <div className="flex flex-col md:flex-row">
          <div className="md:w-1/2 mb-8 md:mb-0 md:pr-8">
            <h2 className="text-3xl font-bold mb-6 text-snap-dark">
              For Users
            </h2>
            <p className="text-lg mb-4 text-snap-gray">
              e-shop Platform connects you with local vendors for all your tech
              needs. Find products, services, and more with just a few taps.
            </p>

            <div className="mb-8 bg-snap-lightgray p-6 rounded-lg">
              <div className="flex items-center mb-4">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-6 w-6 text-snap-red mr-3"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
                  />
                </svg>
                <p className="text-snap-dark font-medium">Free Shipping</p>
              </div>
              <p className="text-snap-gray text-sm">
                Enjoy free shipping on all orders over $50. Fast delivery right
                to your doorstep.
              </p>
            </div>

            <div className="mb-8 bg-snap-lightgray p-6 rounded-lg">
              <div className="flex items-center mb-4">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-6 w-6 text-snap-red mr-3"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"
                  />
                </svg>
                <p className="text-snap-dark font-medium">Quality Guarantee</p>
              </div>
              <p className="text-snap-gray text-sm">
                All products come with a 30-day money-back guarantee. Shop with
                confidence.
              </p>
            </div>

            <div className="bg-snap-lightgray p-6 rounded-lg">
              <div className="flex items-center mb-4">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-6 w-6 text-snap-red mr-3"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z"
                  />
                </svg>
                <p className="text-snap-dark font-medium">Secure Payments</p>
              </div>
              <p className="text-snap-gray text-sm">
                Your transactions are protected with industry-leading encryption
                and security protocols.
              </p>
            </div>
          </div>

          <div className="md:w-1/2 bg-snap-light p-6 rounded-lg shadow-md border border-gray-200">
            <h3 className="text-2xl font-semibold mb-4 text-snap-dark">
              Get Early Access
            </h3>
            {formSubmitted ? (
              <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded">
                <p>
                  Thank you for registering! We'll notify you when the e-shop
                  Platform launches.
                </p>
              </div>
            ) : (
              <form onSubmit={handleSubmit}>
                {error && (
                  <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
                    <p>{error}</p>
                  </div>
                )}

                <div className="mb-4">
                  <label htmlFor="name" className="block text-snap-gray mb-2">
                    Full Name <span className="text-snap-red">*</span>
                  </label>
                  <input
                    type="text"
                    id="name"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    required
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-snap-red"
                  />
                </div>

                <div className="mb-4">
                  <label htmlFor="phone" className="block text-snap-gray mb-2">
                    WhatsApp / Phone Number{" "}
                    <span className="text-snap-red">*</span>
                  </label>
                  <input
                    type="tel"
                    id="phone"
                    name="phone"
                    value={formData.phone}
                    onChange={handleChange}
                    required
                    placeholder="+1 123 456 7890"
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-snap-red"
                  />
                  <p className="text-xs text-snap-gray mt-1">
                    We'll use this to notify you about our launch and special
                    offers
                  </p>
                </div>

                <div className="mb-4">
                  <p className="block text-snap-gray mb-2">
                    I'm interested in (select all that apply):
                  </p>
                  <div className="grid grid-cols-2 gap-2">
                    <label className="flex items-center">
                      <input
                        type="checkbox"
                        name="interests"
                        value="smartphones"
                        checked={formData.interests.includes("smartphones")}
                        onChange={handleCheckboxChange}
                        className="mr-2"
                      />
                      <span className="text-snap-gray">Smartphones</span>
                    </label>
                    <label className="flex items-center">
                      <input
                        type="checkbox"
                        name="interests"
                        value="laptops"
                        checked={formData.interests.includes("laptops")}
                        onChange={handleCheckboxChange}
                        className="mr-2"
                      />
                      <span className="text-snap-gray">Laptops</span>
                    </label>
                    <label className="flex items-center">
                      <input
                        type="checkbox"
                        name="interests"
                        value="audio"
                        checked={formData.interests.includes("audio")}
                        onChange={handleCheckboxChange}
                        className="mr-2"
                      />
                      <span className="text-snap-gray">Audio Devices</span>
                    </label>
                    <label className="flex items-center">
                      <input
                        type="checkbox"
                        name="interests"
                        value="gaming"
                        checked={formData.interests.includes("gaming")}
                        onChange={handleCheckboxChange}
                        className="mr-2"
                      />
                      <span className="text-snap-gray">Gaming</span>
                    </label>
                    <label className="flex items-center">
                      <input
                        type="checkbox"
                        name="interests"
                        value="smarthome"
                        checked={formData.interests.includes("smarthome")}
                        onChange={handleCheckboxChange}
                        className="mr-2"
                      />
                      <span className="text-snap-gray">Smart Home</span>
                    </label>
                    <label className="flex items-center">
                      <input
                        type="checkbox"
                        name="interests"
                        value="accessories"
                        checked={formData.interests.includes("accessories")}
                        onChange={handleCheckboxChange}
                        className="mr-2"
                      />
                      <span className="text-snap-gray">Accessories</span>
                    </label>
                  </div>
                </div>

                <div className="mb-6">
                  <label className="flex items-start cursor-pointer">
                    <input
                      type="checkbox"
                      name="marketingConsent"
                      checked={formData.marketingConsent}
                      onChange={handleCheckboxChange}
                      className="mt-1 mr-2"
                    />
                    <span className="text-sm text-snap-gray">
                      I agree to receive updates, promotions, and offers from
                      e-shop Platform via WhatsApp or SMS. We'll never share
                      your contact information with third parties without your
                      permission.
                    </span>
                  </label>
                </div>

                <button
                  type="submit"
                  className="w-full bg-snap-red hover:bg-snap-dark text-snap-light font-bold py-2 px-4 rounded-md transition duration-300"
                >
                  Join the Waitlist
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    </section>
  );
};

export default UserSection;
